ALTER TABLE "reach_contacts" ADD COLUMN "withdrawn_at" timestamp with time zone;--> statement-breakpoint
CREATE VIEW "public"."reach_invites" AS (SELECT m.id, m.contact_id, m.account_id, c.handle, c.url, c.name, c.headline, c.niche, c.person_id, c.company_id, c.found_in, NULLIF(m.body, '') AS note, CASE WHEN c.connected_at IS NOT NULL THEN 'accepted' WHEN c.withdrawn_at IS NOT NULL THEN 'withdrawn' WHEN m.state = 'sent' AND c.state = 'enrolled' THEN 'pending' WHEN m.state = 'sent' THEN 'ended' WHEN m.state IN ('queued', 'sending') THEN 'queued' ELSE m.state END AS status, coalesce(m.state_reason, c.state_reason) AS state_reason, m.created_at AS queued_at, m.sent_at, c.connected_at, c.withdrawn_at FROM reach_messages m JOIN reach_contacts c ON c.id = m.contact_id WHERE m.kind = 'connect' AND m.direction = 'out');